insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)values('question-intake','question-intake',false,26214400,array['application/pdf','image/png','image/jpeg','image/webp'])on conflict(id)do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
create table dm_private.question_intake_assets(id uuid primary key default gen_random_uuid(),storage_path text unique not null,original_name text not null,mime_type text not null check(mime_type in('application/pdf','image/png','image/jpeg','image/webp')),byte_size integer not null check(byte_size between 1 and 26214400),status text not null default'uploaded'check(status in('uploaded','extracting','extracted','failed','reviewed')),uploaded_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table dm_private.question_intake_assets enable row level security;revoke all on dm_private.question_intake_assets from anon,authenticated;
create or replace function public.register_question_intake_asset(p_storage_path text,p_original_name text,p_mime_type text,p_byte_size integer,p_uploaded_by uuid)returns uuid language plpgsql security definer set search_path=pg_catalog,dm_private,public as $$declare v uuid;begin if auth.role()is distinct from'service_role'then raise exception'Forbidden';end if;if not exists(select 1 from dm_private.admins where user_id=p_uploaded_by)then raise exception'Admin access required';end if;insert into dm_private.question_intake_assets(storage_path,original_name,mime_type,byte_size,uploaded_by)values(p_storage_path,p_original_name,p_mime_type,p_byte_size,p_uploaded_by)returning id into v;return v;end$$;
create or replace function public.admin_question_intake_assets()returns jsonb language plpgsql stable security definer set search_path=pg_catalog,dm_private,public as $$begin if not public.is_dmocks_admin()then raise exception'Admin access required';end if;return(select coalesce(jsonb_agg(jsonb_build_object('id',id,'name',original_name,'mimeType',mime_type,'byteSize',byte_size,'status',status,'createdAt',created_at)order by created_at desc),'[]')from dm_private.question_intake_assets);end$$;
create or replace function public.admin_promote_intake_asset(p_asset_id uuid,p_payload jsonb)returns uuid language plpgsql security definer set search_path=pg_catalog,dm_private,public as $$declare v uuid;begin if not public.is_dmocks_admin()then raise exception'Admin access required';end if;if jsonb_typeof(p_payload)<>'object'or not(p_payload?'prompt')then raise exception'Extracted question payload is invalid';end if;insert into dm_private.question_drafts(source_type,source_name,payload,created_by)select case when mime_type='application/pdf'then'pdf'else'photo'end,original_name,p_payload,auth.uid()from dm_private.question_intake_assets where id=p_asset_id and status in('uploaded','extracted')returning id into v;if v is null then raise exception'Intake asset unavailable';end if;update dm_private.question_intake_assets set status='reviewed',updated_at=now()where id=p_asset_id;return v;end$$;
revoke all on function public.register_question_intake_asset(text,text,text,integer,uuid)from public,anon,authenticated;grant execute on function public.register_question_intake_asset(text,text,text,integer,uuid)to service_role;
revoke all on function public.admin_question_intake_assets(),public.admin_promote_intake_asset(uuid,jsonb)from public,anon;grant execute on function public.admin_question_intake_assets(),public.admin_promote_intake_asset(uuid,jsonb)to authenticated;
